   "question": [
    "¿Cómo introduce el hablante este hecho en su conversación?",
    "Ako hovoriaci prináša túto udalosť do rozhovoru?"
   ],
   "body": [
    [
     "Las dos formas pueden contar hechos terminados. Aquí damos mucho espacio al compuesto de la conversación que nos interesa. El simple sigue siendo útil para narrar episodios y comprender otros estilos y hablantes.",
     "Oba tvary môžu hovoriť o dokončených dejoch. Tu dávame veľa priestoru zloženému času z rozhovorov, ktoré nás zaujímajú. Jednoduchý tvar zostáva užitočný pri rozprávaní epizód a porozumení iným štýlom a ľuďom."
    ],
    [
     "Estas parejas muestran dos maneras de contar, no una respuesta correcta y otra incorrecta. La traducción eslovaca puede coincidir. Escucha el entorno y la intención, no solo una palabra de calendario.",
     "Tieto páry ukazujú dva spôsoby rozprávania, nie správnu a nesprávnu odpoveď. Slovenský preklad môže byť rovnaký. Sledujte prostredie a zámer, nielen slovo z kalendára."
    ]
   ],
   "bridge": [
    "El eslovaco puede decir hovoril som o prečítal som para ambas formas, según el verbo. No hay que fabricar una diferencia que no necesita expresar.",
    "Slovenčina môže pri oboch tvaroch povedať hovoril som alebo prečítal som podľa slovesa. Netreba vyrábať rozdiel, ktorý nepotrebuje vyjadriť."
   ],
   "build": [
    "He + hablado frente a hablé. El compuesto usa haber; el simple lleva la información en una sola palabra.",
    "He + hablado oproti hablé. Zložený tvar používa haber; jednoduchý nesie informáciu v jedinom slove."
   ],
   "avoid": [
    "Ni compuesto = acción sin terminar, ni simple = acción breve. Y no todas las personas de España eligen igual.",
    "Ani zložený = nedokončený dej, ani jednoduchý = krátky dej. A nie všetci ľudia v Španielsku volia rovnako."
   ]
